# Simulate abnormal vital checking.
def patch_patient_risk_score(func):
    def wrapper(hospital, patient_id):
        patient = hospital.get_patient(patient_id)
        records = hospital.get_recent_records(patient_id, 90)
        abnormal = any(r.get('abnormal_vitals', False) for r in records)
