        self._patients = patients   # dict patient_id: MockPatient
        self._records = records     # dict patient_id: list of record dicts

    def get_patient(self, patient_id):
        return self._patients[patient_id]

    def get_recent_records(self, patient_id, days):
        # Returns the latest records within 90 days (mock: just return all for simplicity)
        return self._records.get(patient_id, [])

def abnormal_vitals(records):
    # Checks if any record in records has 'vitals_abnormal' True. (as a mock logic)
    for r in records:
        if r.get('vitals_abnormal', False):
            return True
    return False

def patient_risk_score(hospital, patient_id):
    '''
    Create a function called patient_risk_score that takes a Hospital object and patient_id. Calculate risk score using formula: (patient.age / 100 * 30) + (patient.get_total_conditions() * 5 * 25/100) + (patient.get_average_severity() * 10 * 25/100) + (20 if recent records have abnormal vitals else 0). Use hospital.get_patient(patient_id) and hospital.get_recent_records(patient_id, 90). Returns: float between 0.0 and 100.0.
    '''
    patient = hospital.get_patient(patient_id)
    records = hospital.get_recent_records(patient_id, 90)
    score = (patient.age/100 * 30) + \
        (patient.get_total_conditions() * 5 * 0.25) + \
        (patient.get_average_severity() * 10 * 0.25) + \
        (20 if abnormal_vitals(records) else 0)
    return min(100.0, max(0.0, score))  # Boundaries

